export type Activity = 'read' | 'hammer' | 'conveyor' | 'walk' | 'rain' | 'ok'

export const STAGE_ROWS = 4

const H = STAGE_ROWS * 2

const BG = 0x16161d
const CURTAIN = 0x9e1b2f
const CURTAIN_DK = 0x6e1220
const FLOOR = 0x6b4423
const FLOOR_LT = 0x85572d
const ORANGE = 0xff8a1f
const ORANGE_LT = 0xffc27a
const SHIRT = 0xd2570a
const PANTS = 0x7a3a0a
const EYE = 0x14141a
const CREAM = 0xf3e9d2
const WHITE = 0xffffff
const BROWN = 0x7b3f1d
const GRAY = 0x9aa0aa
const GRAY_DK = 0x585d66
const YELLOW = 0xffe14d
const BELT = 0x3a3a44
const BELT_LT = 0x6a6a78
const TAN = 0xc9923f
const TAN_DK = 0x8c5f1c
const CLOUD = 0x59606b
const DROP = 0x4aa8ff
const DROP_LT = 0x9ad0ff

type Canvas = { W: number; px: number[] }

const put = (c: Canvas, x: number, y: number, color: number) => {
  if (x >= 0 && x < c.W && y >= 0 && y < H) {
    c.px[y * c.W + x] = color
  }
}

const rect = (c: Canvas, x: number, y: number, w: number, h: number, color: number) => {
  for (let j = 0; j < h; j++) {
    for (let i = 0; i < w; i++) {
      put(c, x + i, y + j, color)
    }
  }
}

const backdrop = (c: Canvas) => {
  c.px.fill(BG)
  rect(c, 0, 7, c.W, 1, FLOOR)
  for (let x = 1; x < c.W; x += 3) {
    put(c, x, 7, FLOOR_LT)
  }
  for (let y = 0; y < 7; y++) {
    put(c, 0, y, CURTAIN_DK)
    put(c, 1, y, y % 3 === 0 ? CURTAIN_DK : CURTAIN)
    put(c, c.W - 1, y, CURTAIN_DK)
    put(c, c.W - 2, y, y % 3 === 0 ? CURTAIN_DK : CURTAIN)
  }
}

const guy = (c: Canvas, gx: number, step: number, rightArm: [number, number][]) => {
  put(c, gx + 2, 0, ORANGE_LT)
  rect(c, gx, 1, 5, 2, ORANGE)
  put(c, gx + 1, 2, EYE)
  put(c, gx + 3, 2, EYE)
  rect(c, gx, 3, 5, 2, SHIRT)
  put(c, gx - 1, 4, ORANGE)
  for (const [ax, ay] of rightArm) {
    put(c, gx + ax, ay, ORANGE)
  }
  const a = step === 0 ? gx + 1 : gx + 2
  const b = step === 0 ? gx + 3 : gx + 2
  rect(c, a, 5, 1, 2, PANTS)
  rect(c, b, 5, 1, 2, PANTS)
}

const read = (c: Canvas, f: number) => {
  const gx = 6
  guy(c, gx, 0, [[5, 3], [5, 4]])
  const bx = gx + 6
  rect(c, bx, 3, 6, 3, CREAM)
  rect(c, bx + 3, 3, 1, 3, BROWN)
  put(c, bx + 1, 4, GRAY)
  put(c, bx + 4, 4, GRAY)
  const p = Math.floor(f / 2) % 6
  const x = bx + 5 - p
  put(c, x, 2, CREAM)
  rect(c, x, 3, 1, 3, WHITE)
}

const hammer = (c: Canvas, f: number) => {
  const gx = 4
  const ax = gx + 9
  rect(c, ax, 5, 5, 1, GRAY)
  rect(c, ax + 1, 6, 3, 1, GRAY_DK)
  const isUp = Math.floor(f / 3) % 2 === 0
  if (isUp) {
    guy(c, gx, 0, [[5, 3], [6, 2]])
    rect(c, gx + 6, 0, 4, 1, GRAY)
    rect(c, gx + 7, 1, 1, 2, BROWN)
  } else {
    guy(c, gx, 1, [[5, 4], [6, 4]])
    rect(c, gx + 7, 4, 2, 1, BROWN)
    rect(c, gx + 9, 3, 2, 2, GRAY)
    put(c, gx + 10, 2, YELLOW)
    put(c, gx + 12, 3, YELLOW)
    put(c, gx + 11, 1, ORANGE_LT)
  }
}

const conveyor = (c: Canvas, f: number) => {
  const gx = 3
  const belt0 = gx + 6
  const beltEnd = c.W - 2
  rect(c, belt0, 6, beltEnd - belt0, 1, BELT)
  for (let x = belt0; x < beltEnd; x++) {
    if ((x + f) % 3 === 0) {
      put(c, x, 6, BELT_LT)
    }
  }
  const first = gx + 7
  const span = beltEnd - 3 - first + 1
  const count = c.W >= 28 ? 2 : 1
  for (let k = 0; k < count; k++) {
    const cx = first + ((f + k * 9) % span)
    rect(c, cx, 3, 3, 3, TAN)
    put(c, cx + 1, 4, TAN_DK)
  }
  guy(c, gx, Math.floor(f / 2) % 2, [[5, 4], [6, 4]])
}

const walk = (c: Canvas, f: number) => {
  const lane = Math.max(1, c.W - 4 - 8)
  const t = Math.floor(f / 2) % (lane * 2)
  const gx = 3 + (t < lane ? t : lane * 2 - t)
  guy(c, gx, Math.floor(f / 2) % 2, [[5, 4]])
  const dots = Math.floor(f / 4) % 4
  for (let i = 0; i < dots; i++) {
    put(c, gx + 6 + i * 2, 0, GRAY)
  }
}

const rain = (c: Canvas, f: number) => {
  const gx = Math.floor(c.W / 2) - 2
  rect(c, 2, 0, c.W - 4, 1, CLOUD)
  for (let x = 3; x < c.W - 3; x += 4) {
    put(c, x, 1, CLOUD)
  }
  let i = 0
  for (let x = 2; x < c.W - 2; x += 2) {
    const y = ((f + i * 3) % 6) + 1
    put(c, x, y, i % 2 === 0 ? DROP : DROP_LT)
    i++
  }
  guy(c, gx, 0, [[5, 4]])
  if (f % 24 < 2) {
    put(c, gx + 7, 1, YELLOW)
    put(c, gx + 6, 2, YELLOW)
    put(c, gx + 7, 3, YELLOW)
  }
}

const ok = (c: Canvas, f: number) => {
  const gx = Math.floor(c.W / 2) - 3
  guy(c, gx, 0, [[5, 3], [6, 2]])
  put(c, gx - 1, 3, ORANGE)
  const isOn = Math.floor(f / 3) % 2 === 0
  const ring = isOn ? WHITE : GRAY_DK
  for (let j = 0; j < 3; j++) {
    for (let i = 0; i < 3; i++) {
      if (i !== 1 || j !== 1) {
        put(c, gx + 6 + i, j, ring)
      }
    }
  }
  if (isOn) {
    put(c, gx - 3, 1, YELLOW)
    put(c, gx + 11, 4, YELLOW)
  } else {
    put(c, gx - 4, 3, YELLOW)
    put(c, gx + 12, 2, YELLOW)
  }
}

const SCENES: Record<Activity, (c: Canvas, f: number) => void> = {
  read,
  hammer,
  conveyor,
  walk,
  rain,
  ok,
}

const B64 = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/'

const base64 = (bytes: Uint8Array): string => {
  let out = ''
  for (let i = 0; i < bytes.length; i += 3) {
    const n = (bytes[i] << 16) | ((bytes[i + 1] ?? 0) << 8) | (bytes[i + 2] ?? 0)
    out += B64[(n >> 18) & 63] + B64[(n >> 12) & 63]
    out += i + 1 < bytes.length ? B64[(n >> 6) & 63] : '='
    out += i + 2 < bytes.length ? B64[n & 63] : '='
  }

  return out
}

const paint = (activity: Activity, frame: number, W: number): Canvas => {
  const c: Canvas = { W, px: new Array(W * H).fill(BG) }
  backdrop(c)
  SCENES[activity](c, frame)

  return c
}

export const stageCells = (activity: Activity, frame: number, W: number): string => {
  const c = paint(activity, frame, W)
  const words = new Uint32Array(W * STAGE_ROWS * 3)
  let k = 0
  for (let r = 0; r < STAGE_ROWS; r++) {
    for (let x = 0; x < W; x++) {
      words[k++] = 0x2580
      words[k++] = c.px[r * 2 * W + x]
      words[k++] = c.px[(r * 2 + 1) * W + x]
    }
  }

  return base64(new Uint8Array(words.buffer))
}

const hex = (n: number): string => `#${n.toString(16).padStart(6, '0')}`

export const stageSvg = (activity: Activity, frame: number, W: number, scale: number): string => {
  const c = paint(activity, frame, W)
  let rects = ''
  for (let y = 0; y < H; y++) {
    let x = 0
    while (x < W) {
      const color = c.px[y * W + x]
      let end = x + 1
      while (end < W && c.px[y * W + end] === color) {
        end++
      }
      rects += `<rect x="${x}" y="${y}" width="${end - x}" height="1" fill="${hex(color)}"/>`
      x = end
    }
  }

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${W * scale}" height="${H * scale}" viewBox="0 0 ${W} ${H}" shape-rendering="crispEdges">${rects}</svg>`
}

